export type PropertyInfo = {
    // basics
    id: number;
    name: string;
    component: ObjectType;
    componentSubtype?: number;
    kind: PropertyKind;
    primitiveType?: PrimitiveType;
    enumType?: EnumType;
    default?: any;
    constraint?: TypeConstraintIn;
    fieldType?: FieldType;

    // flags
    isList?: boolean;
    isRequired?: boolean;
    isInternal?: boolean;
    isSystem?: boolean;
    isKernel?: boolean;
    isAutoset?: boolean;
    isComputed?: boolean;
    isRuntime?: boolean;
    isWired?: boolean;
    isStored?: boolean;
    isUnique?: boolean;
    isSensitive?: boolean;
        
    // references
    referenceKind?: ReferenceKind;
    referenceNodes?: NodeType[] | "any";
    referenceStruct?: StructType;
    referenceIsNodeData?: boolean;
}
    
